html:
{%- set company_doc = frappe.get_doc("Company", doc.company) -%}
{%- set cur = doc.currency or "NGN" -%}

{#- LOGO RESOLUTION
    Tries every sensible source in turn, because the logo may live in the letter
    head chosen on the document, in the default letter head, in another letter
    head, or on the Company record. A letter head may also hold its logo inside
    its rich-text Content rather than the Image field, so that is parsed too.
    Stored paths are relative (/files/...), which the PDF engine cannot resolve,
    so the winner is converted to an absolute URL. -#}
{%- set ns = namespace(logo=None) -%}

{%- set lh_candidates = [] -%}
{%- if doc.letter_head -%}{%- set _ = lh_candidates.append(doc.letter_head) -%}{%- endif -%}
{%- set default_lh = frappe.db.get_value("Letter Head", {"is_default": 1}, "name") -%}
{%- if default_lh -%}{%- set _ = lh_candidates.append(default_lh) -%}{%- endif -%}
{%- for lh in frappe.get_all("Letter Head", filters={"disabled": 0}, pluck="name") -%}
  {%- set _ = lh_candidates.append(lh) -%}
{%- endfor -%}

{%- for lh in lh_candidates -%}
  {%- if not ns.logo -%}
    {%- set img = frappe.db.get_value("Letter Head", lh, "image") -%}
    {%- if img -%}
      {%- set ns.logo = img -%}
    {%- else -%}
      {%- set content = frappe.db.get_value("Letter Head", lh, "content") or "" -%}
      {%- if 'src="' in content -%}
        {%- set ns.logo = content.split('src="')[1].split('"')[0] -%}
      {%- elif "src='" in content -%}
        {%- set ns.logo = content.split("src='")[1].split("'")[0] -%}
      {%- endif -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}

{%- if not ns.logo -%}{%- set ns.logo = company_doc.get("company_logo") -%}{%- endif -%}
{%- set logo_url = (ns.logo if (ns.logo and (ns.logo.startswith("http") or ns.logo.startswith("data:")))
                    else (frappe.utils.get_url(ns.logo) if ns.logo else None)) -%}

{#- ADDRESS RESOLUTION
    The invoice only carries an address if one was linked when it was raised.
    Falling back to the party's own Address record means the block is populated
    even on documents where nobody selected an address. -#}
{%- macro addr_of(doctype, name) -%}
  {%- set link = frappe.db.get_value("Dynamic Link",
        {"link_doctype": doctype, "link_name": name, "parenttype": "Address"}, "parent") -%}
  {%- if link -%}
    {%- set a = frappe.get_doc("Address", link) -%}
    {%- set parts = [a.address_line1, a.address_line2, a.city, a.state, a.pincode, a.country] -%}
    {{ parts | select | join("<br>") }}
  {%- endif -%}
{%- endmacro -%}

{%- set company_addr = doc.company_address_display or addr_of("Company", doc.company) -%}
{%- set customer_addr = doc.address_display or addr_of("Customer", doc.customer) -%}
{%- set shipping_addr = doc.shipping_address or customer_addr -%}

{#- SALES REP
    The realtor who introduced the sale is recorded on the Plot Subscription, not on
    the invoice, so it is looked up here. The invoice may link to the subscription
    directly, or reach it through the Sales Order it was raised from. Falling back to
    the login of whoever typed the document is a last resort only. -#}
{%- set ns_rep = namespace(name=None) -%}
{%- set sub = doc.get("plot_subscription") -%}
{%- if not sub and doc.items and doc.items[0].get("sales_order") -%}
  {%- set sub = frappe.db.get_value("Plot Subscription",
        {"sales_order": doc.items[0].sales_order}, "name") -%}
{%- endif -%}
{%- if sub -%}
  {%- set ns_rep.name = frappe.db.get_value("Plot Subscription", sub, "realtor") -%}
{%- endif -%}
{%- if not ns_rep.name and doc.sales_team and doc.sales_team|length -%}
  {%- set ns_rep.name = doc.sales_team[0].sales_person -%}
{%- endif -%}
{%- if not ns_rep.name and doc.get("sales_partner") -%}
  {%- set ns_rep.name = doc.sales_partner -%}
{%- endif -%}

{%- macro money(v) -%}{{ frappe.utils.fmt_money(v or 0, currency=cur) }}{%- endmacro -%}

<!-- ============ HEADER ============ -->
  <div class="agl-headwrap">
    <div class="agl-brand">
      {% if logo_url %}
        <img src="{{ logo_url }}" class="agl-logo">
      {% else %}
        <div class="agl-coname">{{ doc.company }}</div>
      {% endif %}
    </div>

    <div class="agl-title">INVOICE</div>
    <table class="agl-meta">
      <tr><td class="lbl">NUMBER:</td><td class="val strong">{{ doc.name }}</td></tr>
      <tr><td class="lbl">REFERENCE:</td><td class="val">{{ doc.po_no or "" }}</td></tr>
      <tr><td class="lbl">DATE:</td><td class="val strong">{{ frappe.utils.formatdate(doc.posting_date, "dd/MM/yyyy") }}</td></tr>
      <tr><td class="lbl">DUE DATE:</td><td class="val">{{ frappe.utils.formatdate(doc.due_date, "dd/MM/yyyy") if doc.due_date else "" }}</td></tr>
      <tr><td class="lbl">SALES REP:</td><td class="val">{{ ns_rep.name or "" }}</td></tr>
      <tr><td class="lbl">OVERALL DISCOUNT&nbsp;%:</td><td class="val">{{ "%.2f"|format(doc.additional_discount_percentage or 0) }}%</td></tr>
      <tr><td class="lbl">PAGE:</td><td class="val">1/1</td></tr>
    </table>
  </div>

  <!-- ============ FROM / TO ============ -->
  <table class="agl-parties">
    <tr>
      <td class="w50">
        <div class="agl-tag">FROM</div>
        <div class="agl-party">{{ doc.company|upper }}</div>
      </td>
      <td class="w50">
        <div class="agl-tag">TO</div>
        <div class="agl-party">{{ (doc.customer_name or doc.customer)|upper }}</div>
      </td>
    </tr>
    <tr>
      <td>
        {% if company_doc.tax_id %}<div class="agl-sub">VAT NO: <span class="agl-subval">{{ company_doc.tax_id }}</span></div>{% endif %}
      </td>
      <td>
        {% if doc.tax_id %}<div class="agl-sub">CUSTOMER VAT NO: <span class="agl-subval">{{ doc.tax_id }}</span></div>{% endif %}
      </td>
    </tr>
    <tr class="agl-addr-row">
      <td>
        {% if company_addr %}
        <table class="agl-addr">
          <tr>
            <td class="w50">
              <div class="agl-sub">POSTAL ADDRESS:</div>
              <div class="agl-addrtext">{{ company_addr }}</div>
            </td>
            <td class="w50">
              <div class="agl-sub">PHYSICAL ADDRESS:</div>
              <div class="agl-addrtext">{{ company_addr }}</div>
            </td>
          </tr>
        </table>
        {% endif %}
      </td>
      <td>
        {% if customer_addr %}
        <table class="agl-addr">
          <tr>
            <td class="w50">
              <div class="agl-sub">POSTAL ADDRESS:</div>
              <div class="agl-addrtext">{{ customer_addr }}</div>
            </td>
            <td class="w50">
              <div class="agl-sub">PHYSICAL ADDRESS:</div>
              <div class="agl-addrtext">{{ shipping_addr }}</div>
            </td>
          </tr>
        </table>
        {% endif %}
      </td>
    </tr>
  </table>

  <!-- ============ ITEMS ============ -->
  {%- set net = doc.net_total or 0 -%}
  {%- set taxtot = doc.total_taxes_and_charges or 0 -%}
  {%- set vat_pct = ((taxtot / net * 100) if net else 0) -%}
  <table class="agl-items">
    <thead>
      <tr>
        <th class="ih desc">Description</th>
        <th class="ih num">Quantity</th>
        <th class="ih num">Unit Price</th>
        <th class="ih num">Disc %</th>
        <th class="ih num">VAT %</th>
        <th class="ih num">Excl. Total</th>
        <th class="ih num last">Incl. Total</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
        {%- set line_tax = (row.amount or 0) * vat_pct / 100 -%}
        <tr>
          <td class="id desc">{{ row.description or row.item_name }}</td>
          <td class="id num">{{ (row.qty|int) if row.qty and row.qty == row.qty|int else (row.qty or "") }}</td>
          <td class="id num">{{ money(row.rate) }}</td>
          <td class="id num">{{ "%.2f"|format(row.discount_percentage or 0) }}%</td>
          <td class="id num">{{ "%.2f"|format(vat_pct) }}%</td>
          <td class="id num">{{ money(row.amount) }}</td>
          <td class="id num last strong">{{ money((row.amount or 0) + line_tax) }}</td>
        </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- ============ TOTALS ============ -->
  <div class="agl-foot">
    <table class="agl-totals">
      <tr><td class="tl">Total Discount:</td><td class="tv strong">{{ money(doc.discount_amount) }}</td></tr>
      <tr><td class="tl">Total Exclusive:</td><td class="tv strong">{{ money(doc.net_total) }}</td></tr>
      <tr><td class="tl">Total VAT:</td><td class="tv strong">{{ money(doc.total_taxes_and_charges) }}</td></tr>
      <tr><td class="tl">Sub Total:</td><td class="tv strong">{{ money(doc.grand_total) }}</td></tr>
      <tr class="gap"><td colspan="2"></td></tr>
      <tr><td class="tl">Grand Total:</td><td class="tv strong">{{ money(doc.rounded_total or doc.grand_total) }}</td></tr>
    </table>

    <div class="agl-due">
      <div class="agl-duelbl">BALANCE DUE</div>
      <div class="agl-dueval">{{ money(doc.outstanding_amount) }}</div>
    </div>
  </div>

  {% if doc.terms %}<div class="agl-terms">{{ doc.terms }}</div>{% endif %}
</div>

<style>
  /* Frappe's print stylesheet pads every cell generously; these overrides are
     deliberately !important so the compact layout survives it. */
  .agl-inv { font-family: Helvetica, Arial, sans-serif; color:#1a1a1a; font-size:9pt;
             line-height:1.3 !important; }
  .agl-inv table { width:100%; border-collapse:collapse; margin:0 !important; }
  .agl-inv td, .agl-inv th { border:none; vertical-align:top; }
  .agl-inv p { margin:0 !important; padding:0 !important; line-height:1.35 !important; }
  .agl-inv br { line-height:1.35 !important; }
  .w50 { width:50%; }
  .strong { font-weight:700; }

  /* header */
  .agl-headwrap { position:relative; width:100%; }
  .agl-brand { position:absolute; top:0; right:0; text-align:right; }
  .agl-logo { max-height:46px; max-width:200px; display:block;
              margin-left:auto !important; margin-right:0 !important; }
  .agl-coname { font-size:14pt; font-weight:700; color:#2e7d32; line-height:1.15 !important; }
  .agl-title { font-size:25pt; font-weight:700; letter-spacing:-0.5px;
               margin:0 0 7px 0 !important; line-height:1 !important; }
  .agl-meta { width:auto !important; }
  .agl-meta td { padding:0 !important; font-size:8pt; line-height:1.55 !important; height:auto !important; }
  .agl-meta .lbl { color:#666; text-transform:uppercase; padding-right:20px !important; white-space:nowrap; }
  .agl-meta .val { text-align:right; white-space:nowrap; }

  /* parties */
  .agl-inv table.agl-parties { margin-top:32px !important; }
  .agl-parties > tbody > tr > td { padding:0 24px 0 0 !important; }
  .agl-tag { font-size:7.5pt; color:#8a8a8a; letter-spacing:0.6px; line-height:1.3 !important; }
  .agl-party { font-size:12.5pt; font-weight:700; margin:1px 0 7px 0 !important; line-height:1.2 !important; }
  .agl-sub { font-size:7.5pt; color:#666; text-transform:uppercase; letter-spacing:0.3px;
             line-height:1.4 !important; margin:0 !important; }
  .agl-subval { color:#1a1a1a; }
  .agl-addr-row > td { padding-top:9px !important; }
  .agl-addr td { padding:0 10px 0 0 !important; }
  .agl-addrtext { font-size:8pt; line-height:1.35 !important; color:#333; margin-top:1px; }
  .agl-addrtext p { margin:0 !important; line-height:1.35 !important; }

  /* items */
  .agl-inv table.agl-items { margin-top:26px !important; }
  .ih { font-size:8.5pt; font-style:italic; color:#7a7a7a; font-weight:400;
        border-bottom:1px solid #d8d8d8 !important; padding:0 8px 4px 0 !important;
        line-height:1.3 !important; }
  .ih.desc { text-align:left; width:38%; }
  .ih.num { text-align:right; }
  .ih.last { padding-right:0 !important; }
  .id { padding:7px 8px 7px 0 !important; border-bottom:1px solid #ededed !important;
        font-size:8.5pt; line-height:1.35 !important; }
  .id.desc { font-style:italic; }
  .id.num { text-align:right; white-space:nowrap; }
  .id.last { padding-right:0 !important; }

  /* totals */
  .agl-foot { margin-top:22px !important; width:100%; overflow:hidden; }
  .agl-totals { width:44%; float:right; border-top:1px solid #d8d8d8 !important;
                padding-top:7px !important; }
  .agl-totals td { padding:1px 0 !important; font-size:8.5pt; line-height:1.45 !important; }
  .agl-totals .tl { color:#333; }
  .agl-totals .tv { text-align:right; white-space:nowrap; }
  .agl-totals .gap td { padding:3px 0 !important; }
  .agl-due { clear:both; float:right; width:44%; text-align:right; margin-top:10px; }
  .agl-duelbl { font-size:8pt; color:#999; letter-spacing:0.6px; line-height:1.2 !important; }
  .agl-dueval { font-size:16.5pt; font-weight:700; margin-top:1px; line-height:1.15 !important; }
  .agl-terms { clear:both; padding-top:26px; font-size:8pt; color:#555; }
</style>
